class Waypoint {
  constructor(name, latitude, longitude) {
    this.name = name;
    this.latitude = latitude;
    this.longitude = longitude;
  }

  distanceTo(otherWaypoint) {
    const dx = this.latitude - otherWaypoint.latitude;
    const dy = this.longitude - otherWaypoint.longitude;
    return Math.sqrt(dx * dx + dy * dy);
  }
}

#route-planner {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
}

.waypoint-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.waypoint-list li {
  padding: 10px;
  background-color: #f0f0f0;
  border: 1px solid #ccc;
  margin-bottom: 5px;
  animation: fade-in 0.5s ease forwards;
}

@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

// (a) Instantiate three Waypoint objects
const waypoints = [
  new Waypoint('Depot', 34.05, -118.25),
  new Waypoint('Warehouse', 34.07, -118.20),
  new Waypoint('Customer', 34.10, -118.15)
];

// (b) Render each waypoint as a list item
const listEl = document.querySelector('.waypoint-list');

function renderWaypoints() {
  listEl.innerHTML = '';
  waypoints.forEach((wp, idx) => {
    const li = document.createElement('li');
    li.textContent = wp.name;
    li.draggable = true;
    li.dataset.index = idx; // store position for DnD
    listEl.appendChild(li);
  });
}
renderWaypoints();

// (c) Drag‑and‑drop handlers
let dragSrcIdx = null;

listEl.addEventListener('dragstart', e => {
  if (e.target && e.target.nodeName === 'LI') {
    dragSrcIdx = Number(e.target.dataset.index);
    e.dataTransfer.effectAllowed = 'move';
  }
});

listEl.addEventListener('dragover', e => {
  e.preventDefault(); // allow drop
});

listEl.addEventListener('drop', e => {
  e.preventDefault();
  if (e.target && e.target.nodeName === 'LI') {
    const dropIdx = Number(e.target.dataset.index);
    // (d) Update underlying array order
    const [moved] = waypoints.splice(dragSrcIdx, 1);
    waypoints.splice(dropIdx, 0, moved);
    renderWaypoints();
  }
});

