IF OBJECT_ID('dbo.Orders_Archive', 'U') IS NULL
BEGIN
    SELECT * INTO dbo.Orders_Archive FROM dbo.Orders WHERE 1 = 0; -- creates empty copy
END

/* Move orders older than 30 days to the archive */
INSERT INTO dbo.Orders_Archive (OrderID, CustomerID, OrderDate, TotalAmount)
SELECT OrderID, CustomerID, OrderDate, TotalAmount
FROM dbo.Orders
WHERE OrderDate < DATEADD(day, -30, GETDATE());

/* Delete the archived rows from the original table */
